import{_ as t,o,c as d,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant Settings — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Settings — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/tenant-settings"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Settings — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/tenant-settings"}]]},"headers":[],"relativePath":"developer-guide/tenant-settings.md","filePath":"developer-guide/tenant-settings.md","lastUpdated":1787349040000}'),n={name:"developer-guide/tenant-settings.md"};function c(s,e,i,r,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-settings-—-developer-guide" tabindex="-1">Tenant Settings — Developer Guide <a class="header-anchor" href="#tenant-settings-—-developer-guide" aria-label="Permalink to &quot;Tenant Settings — Developer Guide&quot;">​</a></h1><h2 id="core-types" tabindex="-1">Core types <a class="header-anchor" href="#core-types" aria-label="Permalink to &quot;Core types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th></tr></thead><tbody><tr><td><code>App\\Support\\TenantSettingDefinitions</code></td><td>Catalog of overridable keys + sensitive keys (includes <code>task_reminder_time</code>, <code>email_notifications</code>, attendance office-hour keys, <code>meetings_default_provider</code>, <code>trash.retention_days</code>, <code>team-chat.retention_days</code>, <code>session_lifetime_minutes</code>)</td></tr><tr><td><code>App\\Services\\Tenant\\TenantSettingService</code></td><td>Hierarchy resolver, cache, branding uploads, runtime mail/config, public bootstrap</td></tr><tr><td><code>App\\Services\\Storage\\FileUploadService</code></td><td>Disk-agnostic store/replace/delete/url (shared with Central)</td></tr><tr><td><code>TenantSettingController</code></td><td>Authenticated list/update, test-mail, branding upload</td></tr><tr><td><code>PublicSettingsController</code> (tenant)</td><td><code>GET /api/tenant/v1/public/settings</code> — resolved payload, no secrets</td></tr><tr><td><code>InitializeTenancy</code></td><td>After tenancy init, calls <code>TenantSettingService::applyRuntimeConfig()</code></td></tr></tbody></table><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p><code>TenantSettingService::resolve($key)</code> returns <code>{ value, source }</code> where <code>source</code> is one of:</p><ul><li><code>tenant</code> — row in <code>tenant_settings</code></li><li><code>workspace</code> — Tenant model column (<code>workspace_name</code>, <code>company_name</code>, <code>timezone</code>, …)</li><li><code>central</code> — <code>SystemSettingService</code></li><li><code>system</code> — hard-coded / config fallback</li></ul><p>Business code must call the service (<code>applicationName()</code>, <code>logoUrl()</code>, <code>supportEmail()</code>, <code>buttonColor()</code>, <code>usesCustomMailProvider()</code>, …) instead of branching on raw settings.</p><p><code>task_reminder_time</code> is a string <code>H:i</code> value (default <code>09:00</code>) under the <code>general</code> group (UI label: <strong>Daily Reminder Time</strong>). <code>crm:send-due-notifications</code> compares <code>now($workspaceTimezone)-&gt;format(&#39;H:i&#39;)</code> against that value so digests and daily CRM summaries gate on the workspace timezone even if the scheduler process default remains UTC. <code>applyRuntimeConfig()</code> still sets PHP <code>app.timezone</code> / <code>date_default_timezone_set</code> for <code>today()</code> / due-date queries and Sanctum; mail overlay failures must not undo that timezone.</p><p><code>email_notifications</code> is a JSON object under the <code>notifications</code> group. Keys (<code>task_assigned</code>, <code>task_status</code>, <code>task_mentioned</code>, <code>lead_follow_up_created</code>, <code>lead_follow_up_due</code>, <code>lead_mentioned</code>, <code>meeting_events</code>, <code>module_assigned</code>) default to <code>false</code>. Event notifications call <code>ResolvesOptionalMailChannel::withOptionalMail()</code> so only the <code>mail</code> channel is gated; <code>database</code> / <code>broadcast</code> / <code>webpush</code> stay on. Digests and auth mail never consult this map. Resolve via <code>EmailNotificationPreferenceService</code> / <code>TenantSettingService::resolve(&#39;email_notifications&#39;)</code>.</p><p>Attendance group keys (system defaults when unset): <code>office_start_time</code> (<code>09:00</code>), <code>office_end_time</code> (<code>18:00</code>), <code>attendance_grace_minutes</code> (<code>15</code>), <code>work_week_days</code> (<code>[1,2,3,4,5]</code> ISO weekdays). Used by login check-in and <code>PayPeriodCalculator</code>.</p><p><code>meetings_default_provider</code> is <code>none</code> | <code>google_meet</code> | <code>zoom</code> (default <code>none</code>) under the <code>general</code> group. It preselects the Meetings schedule form; OAuth connections remain on Meetings → Integrations.</p><p><code>session_lifetime_minutes</code> is an integer under the <code>security</code> group (<code>0</code>–<code>43200</code>). <code>0</code> means never expire: public bootstrap exposes it, SPA idle logout is skipped, and <code>TenantAuthBootstrapService::issueAccessToken()</code> creates a Sanctum token with <code>expires_at = null</code>. When unset, resolution falls back to Central <code>session_lifetime_minutes</code>.</p><p>Invoice PDF company/payment keys (<code>invoices</code> group, workspace-only — no Central fallback): <code>company_tagline</code>, <code>company_address</code>, <code>company_phone</code>, <code>company_website</code>, <code>invoice_payment_terms</code>, <code>invoice_bank_name</code>, <code>invoice_bank_account_name</code>, <code>invoice_bank_account_number</code>, <code>invoice_bank_iban</code>, <code>invoice_bank_swift</code>, <code>invoice_default_notes</code>. Edited in SPA <strong>Settings → Branding</strong> (with logo / <code>button_color</code> / <code>support_email</code>). <code>CustomerInvoicePdfService</code> embeds the tenant logo as a data URI (Dompdf remote URLs disabled) and includes these keys in the PDF cache fingerprint.</p><p><code>team-chat.retention_days</code> is an integer under the <code>team-chat</code> group (Team Chat module). Allowed product values: <strong>30</strong>, <strong>90</strong>, <strong>365</strong>, or <strong>0</strong> (forever). Default when unset is <strong>0</strong> (keep forever). The scheduled command <code>team-chat:purge-expired</code> permanently deletes messages older than the window when <code>days &gt; 0</code>; attachments are removed with those messages. Resolve via <code>TenantSettingService::get(&#39;team-chat.retention_days&#39;, 0, $tenant)</code>.</p><p><code>trash.retention_days</code> is an integer under the <code>general</code> group. Allowed product values: <strong>30</strong>, <strong>90</strong>, <strong>365</strong>, or <strong>0</strong> (forever). Default when unset is <strong>0</strong> (keep SoftDeletes rows until manual force-delete). Validated in <code>UpdateTenantSettingsRequest</code> (<code>in:0,30,90,365</code>). The scheduled command <code>trash:purge-expired</code> force-deletes soft-deleted rows older than the window for models in <code>App\\Support\\TrashPurgeRegistry</code> (CRM/module SoftDeletes — excludes Users, Team Chat, EmailAccount disconnect lifecycle, and IMAP <code>EmailMessage</code>). Resolve via <code>TenantSettingService::get(&#39;trash.retention_days&#39;, 0, $tenant)</code>. Always schedule the command (<code>withoutOverlapping(120)</code>); it no-ops when the setting is <code>0</code>.</p><h2 id="timezone-and-scheduled-datetimes" tabindex="-1">Workspace timezone convention <a class="header-anchor" href="#timezone-and-scheduled-datetimes" aria-label="Permalink to &quot;Workspace timezone convention {#timezone-and-scheduled-datetimes}&quot;">​</a></h2><p><strong>Rule (all current and future tenant modules):</strong> One workspace timezone (<code>Settings → General → Timezone</code>, e.g. <code>Asia/Karachi</code>) is the wall-clock source of truth for <strong>all</strong> tenant date/time behavior. Every shipped module and every new module must honor it. Do <strong>not</strong> invent a second timezone per module. Server / process UTC is for storage and wire format only — never for user-facing scheduling clocks.</p><p>This is part of the <a href="/developer-guide/module-development">Module Development Standard</a> Definition of Done.</p><h3 id="what-uses-the-workspace-timezone-today" tabindex="-1">What uses the workspace timezone today <a class="header-anchor" href="#what-uses-the-workspace-timezone-today" aria-label="Permalink to &quot;What uses the workspace timezone today&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Setting / field</th><th>Behavior when timezone is <code>Asia/Karachi</code></th></tr></thead><tbody><tr><td>Daily Reminder Time</td><td><code>task_reminder_time</code></td><td>Digests and daily CRM summaries send at that <strong>Karachi</strong> wall clock (compare <code>now($workspaceTimezone)</code>), not server UTC</td></tr><tr><td>Task due dates</td><td><code>tasks.due_at</code></td><td>Entered/shown in workspace TZ; stored as UTC instants</td></tr><tr><td>Lead follow-ups</td><td><code>lead_follow_ups.due_at</code></td><td>Same as tasks — display/edit in workspace TZ; due/overdue alerts use workspace “today”</td></tr><tr><td>Meetings / calendar</td><td><code>starts_at</code> / <code>ends_at</code> / <code>remind_at</code></td><td>Form locked to workspace TZ; list/detail format in that TZ</td></tr><tr><td>Attendance login check-in</td><td>“today” + <code>check_in</code></td><td><code>Carbon::now($workspaceTimezone)</code> for date and clock; late vs present uses office hours in that TZ</td></tr><tr><td>Office hours</td><td><code>office_start_time</code> / <code>office_end_time</code> / grace</td><td>Separate clocks from Daily Reminder Time, but same workspace timezone</td></tr><tr><td>Work week / payroll calendar</td><td><code>work_week_days</code></td><td>Working days interpreted with workspace-local dates</td></tr></tbody></table><p>Future modules with due dates, schedules, office hours, digests, or “today” logic must extend this table the same way — reuse workspace timezone; do not add a module-scoped timezone setting unless product explicitly requires multi-region offices in one tenant.</p><p>Wall-clock settings (<code>H:i</code> strings such as Daily Reminder Time and office start/end) are always <strong>local to the workspace timezone</strong>. Absolute scheduled datetimes are stored as UTC and projected into that timezone for UI and business “today/due” logic.</p><h3 id="module-obligations" tabindex="-1">Module obligations <a class="header-anchor" href="#module-obligations" aria-label="Permalink to &quot;Module obligations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Obligation</th><th>Detail</th></tr></thead><tbody><tr><td>Display / edit</td><td>SPA uses <code>SaaS-Frontend/src/lib/datetime.ts</code> + <code>useSettingsStore</code> timezone</td></tr><tr><td>Absolute datetimes</td><td>Backend <code>UtcDateTime</code> cast + <code>UtcIso</code> on API resources; SQL vs those columns uses <code>App\\Support\\UtcInstant</code> (<code>now(&#39;UTC&#39;)</code> / workspace day bounds converted to UTC) — never bind bare <code>now()</code> / <code>today()</code></td></tr><tr><td>Wall-clock settings</td><td><code>H:i</code> strings interpreted in workspace TZ only</td></tr><tr><td>Schedulers / gates</td><td>Prefer <code>now($workspaceTimezone)</code> / <code>Carbon::now($timezone)</code> over bare <code>now()</code> when process TZ may be UTC</td></tr><tr><td>Runtime config</td><td>Rely on <code>applyRuntimeConfig()</code>; never assume server <code>APP_TIMEZONE</code></td></tr><tr><td>Docs</td><td>User/developer guides must state times follow Settings → General → Timezone</td></tr></tbody></table><h3 id="implementation-notes" tabindex="-1">Implementation notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation notes&quot;">​</a></h3><ul><li><code>applyRuntimeConfig()</code> sets PHP <code>app.timezone</code> and <code>date_default_timezone_set</code> to the resolved workspace timezone (for <code>now()</code> / <code>today()</code>, Sanctum expiry comparisons, reminder gates, and template placeholders). Apply timezone <strong>before</strong> mail overlay; mail failures must not leave the process on server UTC.</li><li>Scheduled / absolute fields the SPA sends as UTC ISO (meetings, calendar events, task due times, lead follow-ups) use <code>App\\Casts\\UtcDateTime</code> so naive DB values are always read/written as <strong>UTC</strong>, then projected into <code>app.timezone</code> for in-app Carbon. API resources serialize those fields with <code>App\\Support\\UtcIso</code> (unambiguous UTC ISO-8601). Do <strong>not</strong> use the default <code>datetime</code> cast for new absolute scheduling columns when <code>app.timezone</code> may be non-UTC.</li><li>SQL filters against those UTC columns (<code>due_at &lt; now</code>, due today / this week) must use <code>App\\Support\\UtcInstant</code> (<code>now()</code>, <code>dayBounds()</code>, <code>startOfWeek()</code> / <code>endOfWeek()</code>). Binding workspace <code>now()</code> / <code>today()</code> compares Karachi (or any non-UTC) wall clock to UTC storage and falsely marks upcoming due times as overdue. In-memory Carbon after the cast is already in <code>app.timezone</code> and may use <code>now()</code> / <code>startOfDay()</code>. Announcements visibility uses the same UTC instant compare.</li><li>Reminder gates in <code>crm:send-due-notifications</code> must compare against <code>now($workspaceTimezone)</code>, not bare <code>now()</code>, so scheduler workers stuck on UTC still honor the workspace clock.</li><li>Attendance login check-in must resolve “today” / check-in / late threshold with an explicit workspace timezone (<code>Carbon::now($timezone)</code>), not the server default.</li><li>SPA display/edit helpers live in <code>SaaS-Frontend/src/lib/datetime.ts</code> (<code>formatAppDateTime</code>, <code>appLocalInputToIso</code>, <code>isoToAppLocalInput</code>, …) and use the workspace timezone from <code>useSettingsStore</code>. Do <strong>not</strong> send raw <code>datetime-local</code> strings or <code>.slice(0, 16)</code> of a UTC ISO value — that ignores Settings → General and shows UTC hours in the picker.</li></ul><h2 id="mail-provider" tabindex="-1">Mail provider <a class="header-anchor" href="#mail-provider" aria-label="Permalink to &quot;Mail provider&quot;">​</a></h2><p><code>mail_mode</code> is <code>system</code> (inherit Central via <code>EmailManager</code>) or <code>custom</code> (tenant provider: SMTP / Postmark / Mailgun / …).</p><p><code>usesCustomMailProvider()</code> is true when <code>mail_mode=custom</code>, or (legacy) when <code>mail_host</code> is filled and <code>mail_mode</code> is unset. Backfill with <code>php artisan email:migrate-tenant-mail-modes</code>.</p><p>Queued mail re-applies config via <code>ApplyEmailRuntimeConfig</code> on the <code>emails</code> queue.</p><p>Secrets are encrypted with <code>Crypt</code> and masked as <code>********</code> in the admin API.</p><h2 id="admin-api" tabindex="-1">Admin API <a class="header-anchor" href="#admin-api" aria-label="Permalink to &quot;Admin API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/tenant/v1/settings</code></td><td>Resolved values + <code>source</code> / <code>is_overridden</code></td></tr><tr><td>PUT</td><td><code>/api/tenant/v1/settings</code></td><td><code>{ &quot;settings&quot;: { &quot;key&quot;: value } }</code></td></tr><tr><td>POST</td><td><code>/api/tenant/v1/settings/test-mail</code></td><td><code>{ &quot;email&quot;: &quot;…&quot;, &quot;settings&quot;?: {…} }</code> — structured result</td></tr><tr><td>POST</td><td><code>/api/tenant/v1/settings/branding/{logo|favicon}</code></td><td>Multipart <code>file</code> → <code>FileUploadService</code> under <code>tenants/{uuid}/branding/…</code></td></tr><tr><td>GET</td><td><code>/api/tenant/v1/email-logs</code></td><td>Workspace-scoped delivery logs</td></tr><tr><td>GET</td><td><code>/api/tenant/v1/email-logs/{uuid}</code></td><td>Show one log</td></tr></tbody></table><p>Permissions (<code>config/tenant-permissions.php</code>): <code>settings.list</code>, <code>settings.update</code>, <code>email-logs.list</code>, <code>email-logs.view</code>.</p><p>Object storage: <a href="/developer-guide/object-storage">object-storage.md</a>.</p><p>Requires tenancy (<code>X-Tenant-Domain</code> / domain) + <code>auth:tenant-api</code>.</p><h2 id="public-api" tabindex="-1">Public API <a class="header-anchor" href="#public-api" aria-label="Permalink to &quot;Public API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/tenant/v1/public/settings</code></td><td>Resolved branding + Central-inherited maintenance/password/session</td></tr></tbody></table><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th></tr></thead><tbody><tr><td><code>TenantSettingsPage</code></td><td><code>/settings</code> — General / Security / Branding / Mail</td></tr><tr><td><code>tenantSettingService</code></td><td>Tenant API client</td></tr><tr><td><code>useSettingsStore</code></td><td>Bootstraps from <code>GET …/public/settings</code> on app mount and again after auth settles (session restore, soft login, logout). Tenant path sends Bearer token and, when known, <code>X-Tenant-Domain</code> from the auth workspace so <code>InitializeTenancy</code> can resolve without a host-bound domain. Guest loads may fall back to Central once. In-app brand text stays empty until <code>loaded</code>; tab title falls back to <code>EloSync</code>. Central fallback never overwrites branding that is already loaded (avoids stomping after save/login). Covered by <code>src/store/settings-store.test.ts</code>.</td></tr></tbody></table><h2 id="schema" tabindex="-1">Schema <a class="header-anchor" href="#schema" aria-label="Permalink to &quot;Schema&quot;">​</a></h2><p><code>tenant_settings</code>: <code>tenant_id</code>, <code>key</code>, <code>value</code>, <code>type</code>, <code>group</code>, unique <code>(tenant_id, key)</code>.</p><p>Profile sync: saving <code>company_name</code>, <code>timezone</code>, <code>locale</code>, <code>currency</code>, <code>logo_path</code> also updates the <code>tenants</code> row. <code>workspace_name</code> is stored on the tenant (not as a KV override of Central).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Settings/</span></span></code></pre></div><p>Playwright: <code>npm run test:e2e:tenant-settings</code> in <code>SaaS-Frontend</code>.</p>',46)])])}const h=t(n,[["render",c]]);export{m as __pageData,h as default};
